213	        //
214	        // The self-edge test is load-bearing and was missing: this comment claimed it and the
215	        // code did not do it. A directly self-recursive function is its own singleton SCC, so it
216	        // took this branch with an EMPTY member set — the recursive call then failed the
217	        // `SccMembers.Contains` test, found no entry in `_computedEffects` (it is being computed),
218	        // and fell through to the unknown-call path. Result: `Calor0411 Unknown call target 'Fact'`
219	        // on a function defined ten lines above, then `Calor0410 uses effect 'Unknown:*'`, which
220	        // cannot be declared away — every directly self-recursive function failed to compile,
221	        // on `build`, `run`, `test` and the MCP tools alike. Mutual recursion was unaffected
222	        // because an SCC of size >= 2 populates the set.
223	        //
224	        // A self-recursive singleton goes through the fixpoint loop below, which seeds
225	        // `EffectSet.Empty` and iterates — the same treatment mutual recursion already got.
226	        if (scc.Count == 1 && !HasSelfEdge(scc[0]))
227	        {
228	            var functionId = scc[0];
229	            var function = _callGraphAnalysis.Functions[functionId];
230	            var effects = InferEffects(function, new HashSet<string>());
231	            _computedEffects[functionId] = effects;
232	            return;
233	        }
234	
235	        // For recursive SCCs — mutual, or a single function calling itself — iterate to fixpoint
